#include "language.hpp"
int main(int argc,char**argv){load(argv[1],argv[2],argv[3],argv[4]);ifstream in(argv[5]);string a,b;int id=0;while(in>>a>>b){vector<vector<int>>v(2);for(char x:a)v[0].push_back(x-'a');for(char x:b)v[1].push_back(x-'a');mt19937 rng(23350351+id);float best=-1e30;array<int,26>bp;for(int r=0;r<4;r++){for(int i=0;i<26;i++)P[i]=i;shuffle(P.begin(),P.end(),rng);float now=score(P,v);for(int it=0;it<15000;it++){auto q=P;swap(q[rng()%26],q[rng()%26]);float next=score(q,v),temp=.2+12*(1.-(it%5000)/5000.);if(next>=now||log((rng()+1.)/4294967297.)<(next-now)/temp){P=q;now=next;if(now>best){best=now;bp=P;}}}}cout<<id++<<' '<<best<<'\n';for(int x:bp)cout<<x<<' ';cout<<'\n';for(auto&m:v){for(int x:m)cout<<char('a'+bp[x]);cout<<'\n';}cout<<flush;}}
